<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';
use ReadyFinance\{Core,Finance,Accounting,PartyService,TransactionEditingService,Fault};
$c=new Core();if(!str_starts_with((string)$c->query('SELECT DATABASE()')->fetchColumn(),'readyfinance_entrytest_'))throw new RuntimeException('Synthetic database required.');
$h=(int)$c->query('SELECT MIN(id) FROM households')->fetchColumn();$u=(int)$c->query('SELECT MIN(id) FROM users')->fetchColumn();$key='incoming:'.bin2hex(random_bytes(5));$date=$c->today($h);$f=new Finance($c);$a=new Accounting($c);$s=new PartyService($c);$e=new TransactionEditingService($c);$n=0;
function checkIncoming($ok,$label){global $n;if(!$ok)throw new RuntimeException($label);$n++;echo 'PASS: '.$label.PHP_EOL;}
function rejectIncoming($fn,$label){try{$fn();}catch(Fault $e){checkIncoming($e->status===409,$label);return;}throw new RuntimeException($label);}
$from=$f->create($h,$u,'account',['name'=>'Sending bank '.$key,'type'=>'bank','opening'=>'410000','date'=>$date],$key.':from')['uuid'];
$to=$f->create($h,$u,'account',['name'=>'Receiving bank '.$key,'type'=>'bank','opening'=>'0','date'=>$date],$key.':to')['uuid'];$bank=$c->scope('accounts',$to,$h);
$partyUuid=$s->change($h,$u,['action'=>'create','name'=>'Receipt party '.$key,'kind'=>'person'],$key.':party')['uuid'];$party=array_values(array_filter($s->listing($h)['parties'],fn($p)=>$p['uuid']===$partyUuid))[0];$payable=array_values(array_filter($party['accounts'],fn($l)=>$l['account_kind']==='payable'))[0]['uuid'];$receivable=array_values(array_filter($party['accounts'],fn($l)=>$l['account_kind']==='receivable'))[0]['uuid'];
$batch=$c->insert('import_batches',['uuid'=>Core::uuid(),'household_id'=>$h,'account_id'=>$bank['id'],'created_by'=>$u,'filename'=>'synthetic-incoming.csv','file_hash'=>hash('sha256',$key),'sheet'=>'','source_json'=>'[]','status'=>'review','created_at'=>Core::now()]);
$transfer=function($suffix)use($a,$c,$h,$u,$from,$to,$date,$key,$bank,$batch){$t=$a->post($h,$u,['type'=>'transfer','account_uuid'=>$from,'to_account_uuid'=>$to,'amount'=>'205000','date'=>$date,'description'=>'Synthetic incoming transfer '.$suffix],$key.':'.$suffix);$c->insert('import_links',['household_id'=>$h,'account_id'=>$bank['id'],'fingerprint'=>hash('sha256',$key.$suffix),'transaction_id'=>$t['id'],'batch_id'=>$batch]);return $t;};
$t=$transfer('engine');$d=$e->details($h,$t['uuid']);$m=array_column($d['payload']['bank_movements'],null,'account_uuid');checkIncoming(bccomp($m[$to]['net'],'205000',6)===0&&bccomp($m[$from]['net'],'-205000',6)===0,'Transfer details expose correct receiving and sending bank effects');checkIncoming($d['payload']['statement_accounts']===[$to],'Details identify the bank matched to its statement');
$input=['party_uuid'=>$partyUuid,'payable_uuid'=>$payable,'receivable_uuid'=>$receivable,'account_uuid'=>$to,'amount'=>'205000','date'=>$date,'description'=>'Corrected incoming party receipt','edit_uuid'=>$t['uuid'],'row_version'=>1,'reason'=>'Correct party assignment'];$count=$c->query('SELECT COUNT(*) FROM transactions')->fetchColumn();
rejectIncoming(fn()=>$s->post($h,$u,$input+['action'=>'pay_party'],$key.':wrong-direction'),'Outgoing reclassification of matched incoming transfer is rejected');checkIncoming($c->query('SELECT COUNT(*) FROM transactions')->fetchColumn()===$count&&$c->scope('transactions',$t['uuid'],$h)['status']==='posted','Rejected correction rolls back every new posting');
$r=$s->post($h,$u,$input+['action'=>'receive_party'],$key.':correct');checkIncoming($s->post($h,$u,$input+['action'=>'receive_party'],$key.':correct')['uuid']===$r['uuid'],'Incoming correction retry creates one replacement');checkIncoming(bccomp($c->balance($h,(int)$bank['ledger_id']),'205000',6)===0,'Incoming party correction preserves receiving bank balance');$pl=$c->scope('ledger_accounts',$payable,$h);checkIncoming(bccomp($c->balance($h,(int)$pl['id']),'-205000',6)===0,'Receipt credits party payable for money held or borrowed');checkIncoming((int)$c->query('SELECT transaction_id FROM import_links WHERE household_id=? AND batch_id=?',[$h,$batch])->fetchColumn()===(int)$c->scope('transactions',$r['uuid'],$h)['id'],'Original statement link follows replacement');
$bad=$input;$bad['edit_uuid']=$r['uuid'];$bad['amount']='205001';rejectIncoming(fn()=>$s->post($h,$u,$bad+['action'=>'receive_party'],$key.':wrong-amount'),'Matched incoming amount remains protected');
$preview=$transfer('browser');file_put_contents(dirname(__DIR__,2).'/work/incoming-transfer-preview.json',json_encode(['bank_uuid'=>$to,'bank_name'=>$bank['name'],'party_name'=>$party['name'],'transaction_uuid'=>$preview['uuid']],JSON_THROW_ON_ERROR));
echo $n.' incoming transfer checks passed.'.PHP_EOL;
